<?php declare(strict_types=1); namespace Annam; $title=$order['order_no'];$paymentBlocked=($intent||$order['payment_mode']==='online')&&!in_array($order['payment_status'],['paid','refunded'],true);$subtitle='Placed '.date('j M Y, g:i A',strtotime($order['placed_at'])).' · '.BillingPortal::channelLabel($order['channel']); ?>
<p><a class="o-crumb" href="/manage/orders/">← Orders</a></p>
<?php if($intent): ?><section class="o-card"><h2>Online payment · Razorpay <?= e(strtoupper($intent['mode'])) ?></h2><p>Provider state: <?= e($intent['state']) ?> · <?= e(BillingPortal::paymentLabel($order['payment_status'])) ?></p><?php if($intent['mode']==='test'): ?><p>TEST PAYMENT — no real money is collected and no financial bill is issued.</p><?php endif; ?><?php if($intent['bill_error']): ?><p class="o-flash o-flash-error" role="alert"><?= e($intent['bill_error']) ?></p><?php endif; ?><form method="post" action="reconcile/"><?= csrf() ?><button class="o-btn">Refresh provider status</button></form><?php if($intent['state']==='captured'): ?><form method="post" action="refund/" class="o-form"><label class="o-field"><span>Full refund reason</span><input name="reason" required maxlength="200"></label><?= csrf() ?><label class="o-check"><input name="confirmed_refund" type="checkbox" value="yes" required><span class="o-switch-ui"><i></i></span><b>Confirm full refund</b></label><button class="o-btn">Request full refund</button></form><?php endif; ?></section><?php endif; ?>
<section class="o-card"><h2>Payment &amp; bill</h2><?php if($invoice): ?><a class="o-btn" href="/manage/bills/<?= e($invoice['id']) ?>/">View / print bill <?= e($invoice['number']) ?></a> <a class="o-btn" href="/manage/bills/<?= e($invoice['id']) ?>/download/">Download invoice PDF</a><?php elseif(($intent['mode']??'')==='test'): ?><p>Test payments do not generate real bills.</p><?php elseif($order['payment_status']==='paid'): ?><form method="post" action="bill/"><?= csrf() ?><button class="o-btn o-btn-primary">Generate bill</button></form><?php endif; ?>
<?php if($intent||$order['payment_mode']==='online'): ?><p>Online payments are verified through Razorpay and cannot be marked paid manually.</p><?php elseif(!in_array($order['payment_status'],['paid','refunded'],true)&&$order['status']!=='cancelled'): ?><p>Confirm only after receiving the full payment of <?= money($order['total']) ?>. For COD, confirm after collecting cash.</p><form method="post" action="confirm/" class="o-form"><?= csrf() ?><label class="o-check"><input type="checkbox" name="received" value="1" required><span class="o-switch-ui"><i></i></span><b>Full payment received</b></label><label class="o-field"><span>Payment reference</span><input name="reference" maxlength="120" placeholder="Payment reference / collection note (optional)"></label><button class="o-btn o-btn-primary">Confirm payment &amp; issue bill</button></form><p><a href="/billing/orders/<?= e($order['id']) ?>/">Issue unpaid bill or manage collection →</a></p><?php endif; ?><p><a href="/manage/billing-settings/">Billing settings</a> · Complete once before issuing your first bill.</p></section>
<div class="o-cols"><section class="o-card"><header class="o-card-head"><h2>Items</h2><span class="o-pill o-pill-<?= e($order['status']) ?>"><?= e(ucfirst(str_replace('_',' ',$order['status']))) ?></span></header><ul class="o-rows o-rows-static"><?php foreach($order['items'] as $line): ?><li><span><b><?= e($line['name']) ?></b><small><?= money($line['unit_price']) ?> × <?= e($line['quantity']) ?></small></span><span class="o-money"><?= money($line['line_total']) ?></span></li><?php endforeach; ?><li><span>Subtotal</span><span class="o-money"><?= money($order['subtotal']) ?></span></li><li><span>Delivery</span><span class="o-money"><?= money($order['delivery_fee']) ?></span></li><?php if(Money::parse($order['discount'])): ?><li><span>Discount</span><span>−<?= money($order['discount']) ?></span></li><?php endif; ?><li class="o-total"><span>Total</span><span class="o-money"><?= money($order['total']) ?></span></li></ul></section>
<section class="o-card"><header class="o-card-head"><h2>Customer &amp; delivery</h2></header><p><b><?= e($order['address']['recipient_name']??$customer['name']) ?></b><br><a href="tel:<?= e($order['address']['phone']??$customer['phone']) ?>"><?= e($order['address']['phone']??$customer['phone']) ?></a></p><p class="o-muted"><?= e(implode(', ',array_filter(array_intersect_key($order['address'],array_flip(['line1','line2','landmark','area','city','state','country','pincode','fulfilment']))))) ?></p><p><?= e($order['delivery_date']?date('l, j M',strtotime($order['delivery_date'])):'Collection / shop order') ?> · <?= e(BillingPortal::paymentLabel($order['payment_status'])) ?></p>
<?php if(!in_array($order['status'],['cancelled','delivered'],true)): ?><form method="post" action="status/" class="o-status-form"><?= csrf() ?><p class="o-muted">Move this order to:</p><div class="o-btn-row"><?php foreach(Orders::FLOW[$order['status']]??[] as $status): ?><button class="o-btn o-btn-primary" name="status" value="<?= e($status) ?>" <?= $paymentBlocked?'disabled title="Awaiting verified online payment"':'' ?>><?= e(ucfirst(str_replace('_',' ',$status))) ?></button><?php endforeach; ?><button class="o-btn o-danger-btn" name="status" value="cancelled">Cancel order</button></div><label class="o-field"><span>Order note</span><input name="note" maxlength="200" placeholder="Note (optional, e.g. reason for cancelling)"></label><details><summary>Delivery assignment</summary><label class="o-field"><span>Rider name</span><input name="rider_name" maxlength="120"></label><label class="o-field"><span>Rider phone</span><input name="rider_phone" maxlength="20"></label></details></form><?php endif; ?>
<?php if($events): ?><ol class="o-timeline"><?php foreach($events as $event): ?><li><b><?= e(ucfirst(str_replace('_',' ',$event['to_status']))) ?></b><small><?= e(date('j M, g:i A',strtotime($event['at'])).' · '.$event['actor']) ?></small><?php if($event['note']): ?><p><?= e($event['note']) ?></p><?php endif; ?></li><?php endforeach; ?></ol><?php endif; ?></section></div>
<?php if($charge??null): ?><section class="o-card"><h2>Separate courier charge</h2><p><?= e(Delivery::COURIER) ?></p><?php if(!$charge['dispatched_at']): ?><form method="post" action="courier/" class="o-form"><?= csrf() ?><input type="hidden" name="action" value="dispatch"><label class="o-field">Courier service<input name="courier_name" maxlength="120" required></label><label class="o-field">Tracking number<input name="tracking_number" maxlength="120" required></label><label class="o-field">Courier amount (₹)<input name="amount" type="number" min="0" step="0.01" required></label><p>Advance the order to dispatched before confirming this charge.</p><button class="o-btn o-btn-primary">Confirm dispatched courier charge</button></form><?php else: ?><p><?= e($charge['courier_name'].' · '.$charge['tracking_number']) ?> · <?= money($charge['amount']) ?> · <?= $charge['paid_at']?'Paid':'Awaiting separate payment' ?></p><?php if(!$charge['paid_at']): ?><form method="post" action="courier/" class="o-form"><?= csrf() ?><input type="hidden" name="action" value="paid"><label class="o-field">Receipt reference<input name="reference" maxlength="120" required></label><label class="o-check"><input type="checkbox" name="received" value="1" required><span class="o-switch-ui"><i></i></span><b>Courier payment received</b></label><button class="o-btn">Confirm courier receipt</button></form><?php endif; endif; ?></section><?php endif; ?>